class.description:
Stores values in [code]NSUbiquitousKeyValueStore[/code], Apple's small per-account iCloud key-value store. Values sync across a user's devices signed into the same iCloud account and survive a fresh install, making this the right place for preferences that should follow the user rather than the device.

[codeblocks]
[gdscript]
var cloud_kv = ICloudKV.new()

func _save_settings(json_string):
    if not cloud_kv.set_value("settings", json_string):
        print("Failed to write to iCloud key-value store")

func _load_settings():
    return cloud_kv.get_value("settings")
[/gdscript]
[/codeblocks]
